export const bookingsUpdateNoteResponseLineItemsItemGstBasisPointsMax = 9007199254740991;

export const bookingsUpdateNoteResponseLineItemsItemTaxAmountMin = -9007199254740991;
export const bookingsUpdateNoteResponseLineItemsItemTaxAmountMax = 9007199254740991;

export const bookingsUpdateNoteResponseCreatedAtRegExp = new RegExp('^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z))$');
export const bookingsUpdateNoteResponseUpdatedAtRegExp = new RegExp('^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z))$');


export const BookingsUpdateNoteResponse = zod.object({
  "id": zod.uuid().regex(bookingsUpdateNoteResponseIdRegExp),
  "status": zod.enum(['PENDING', 'CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED', 'NO_SHOW']),
  "source": zod.enum(['PHONE', 'WHATSAPP', 'WALK_IN', 'AIRBNB', 'BOOKING_COM', 'MAKEMYTRIP', 'REFERRAL']),
  "checkIn": zod.iso.date().regex(bookingsUpdateNoteResponseCheckInRegExp),
  "checkOut": zod.iso.date().regex(bookingsUpdateNoteResponseCheckOutRegExp),
  "isWholeProperty": zod.boolean(),
  "rooms": zod.array(zod.object({
  "roomId": zod.uuid().regex(bookingsUpdateNoteResponseRoomsItemRoomIdRegExp),
  "name": zod.string()
})),
  "expiresAt": zod.iso.datetime({"offset":true}).regex(bookingsUpdateNoteResponseExpiresAtRegExp).nullable(),
  "guestName": zod.string().min(1).max(bookingsUpdateNoteResponseGuestNameMax),
  "guestPhone": zod.string().regex(bookingsUpdateNoteResponseGuestPhoneRegExp),
  "guestEmail": zod.email().regex(bookingsUpdateNoteResponseGuestEmailRegExp).nullable(),
  "adults": zod.int().min(1).max(bookingsUpdateNoteResponseAdultsMax),
  "children": zod.int().min(bookingsUpdateNoteResponseChildrenMin).max(bookingsUpdateNoteResponseChildrenMax),
  "roomTotal": zod.int().min(bookingsUpdateNoteResponseRoomTotalMin).max(bookingsUpdateNoteResponseRoomTotalMax),
  "extraGuestTotal": zod.int().min(bookingsUpdateNoteResponseExtraGuestTotalMin).max(bookingsUpdateNoteResponseExtraGuestTotalMax),
  "mealTotal": zod.int().min(bookingsUpdateNoteResponseMealTotalMin).max(bookingsUpdateNoteResponseMealTotalMax),
  "subtotal": zod.int().min(bookingsUpdateNoteResponseSubtotalMin).max(bookingsUpdateNoteResponseSubtotalMax),
  "taxTotal": zod.int().min(bookingsUpdateNoteResponseTaxTotalMin).max(bookingsUpdateNoteResponseTaxTotalMax),
  "total": zod.int().min(bookingsUpdateNoteResponseTotalMin).max(bookingsUpdateNoteResponseTotalMax),
  "overrideTotal": zod.int().min(bookingsUpdateNoteResponseOverrideTotalMin).max(bookingsUpdateNoteResponseOverrideTotalMax).nullable(),
  "overrideReason": zod.string().nullable(),
  "note": zod.string().nullable(),
  "cancellationReason": zod.string().nullable(),
  "gstSlabVersion": zod.string(),
  "lineItems": zod.array(zod.object({
  "roomId": zod.uuid().regex(bookingsUpdateNoteResponseLineItemsItemRoomIdRegExp),
  "date": zod.iso.date().regex(bookingsUpdateNoteResponseLineItemsItemDateRegExp),
  "source": zod.enum(['OVERRIDE', 'WEEKEND', 'BASE']),
  "roomCharge": zod.int().min(bookingsUpdateNoteResponseLineItemsItemRoomChargeMin).max(bookingsUpdateNoteResponseLineItemsItemRoomChargeMax),
  "extraGuests": zod.int().min(bookingsUpdateNoteResponseLineItemsItemExtraGuestsMin).max(bookingsUpdateNoteResponseLineItemsItemExtraGuestsMax),
  "extraGuestCharge": zod.int().min(bookingsUpdateNoteResponseLineItemsItemExtraGuestChargeMin).max(bookingsUpdateNoteResponseLineItemsItemExtraGuestChargeMax),
  "mealCharge": zod.int().min(bookingsUpdateNoteResponseLineItemsItemMealChargeMin).max(bookingsUpdateNoteResponseLineItemsItemMealChargeMax),
  "tariff": zod.int().min(bookingsUpdateNoteResponseLineItemsItemTariffMin).max(bookingsUpdateNoteResponseLineItemsItemTariffMax),
  "gstBasisPoints": zod.int().min(bookingsUpdateNoteResponseLineItemsItemGstBasisPointsMin).max(bookingsUpdateNoteResponseLineItemsItemGstBasisPointsMax),
  "taxAmount": zod.int().min(bookingsUpdateNoteResponseLineItemsItemTaxAmountMin).max(bookingsUpdateNoteResponseLineItemsItemTaxAmountMax)
})),
  "createdBy": zod.string(),
  "updatedBy": zod.string(),
  "createdAt": zod.iso.datetime({"offset":true}).regex(bookingsUpdateNoteResponseCreatedAtRegExp),
  "updatedAt": zod.iso.datetime({"offset":true}).regex(bookingsUpdateNoteResponseUpdatedAtRegExp)
})

